import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"آثار قدیمہ پروٹوکول کا عمومی خاکہ","description":"","frontmatter":{},"headers":[],"relativePath":"ur/0084-考古协议总纲.md","filePath":"ur/0084-考古协议总纲.md"}'),o={name:"ur/0084-考古协议总纲.md"};function h(l,t,i,n,u,_){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="آثار-قدیمہ-پروٹوکول-کا-عمومی-خاکہ" tabindex="-1">آثار قدیمہ پروٹوکول کا عمومی خاکہ <a class="header-anchor" href="#آثار-قدیمہ-پروٹوکول-کا-عمومی-خاکہ" aria-label="Permalink to &quot;آثار قدیمہ پروٹوکول کا عمومی خاکہ&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>84</td></tr><tr><td>ماڈیول</td><td>بین السطح تعامل اور وقت کے اصول</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>آثار قدیمہ پروٹوکول، کاپی آئینہ، الگ تھلگ جگہ، صرف علم کی واپسی، کم آلودگی</td></tr></tbody></table><h2 id="_1-آثار-قدیمہ-پروٹوکول-کی-پوزیشن-اور-اہداف" tabindex="-1">1. آثار قدیمہ پروٹوکول کی پوزیشن اور اہداف <a class="header-anchor" href="#_1-آثار-قدیمہ-پروٹوکول-کی-پوزیشن-اور-اہداف" aria-label="Permalink to &quot;1. آثار قدیمہ پروٹوکول کی پوزیشن اور اہداف&quot;">​</a></h2><p>بین السطح آثار قدیمہ اور وقت کے پیچھے ہٹنے والے آثار قدیمہ اینکر سمبیوسس تہذیب کے لیے تاریخی علم حاصل کرنے اور کائنات کے ارتقاء کو سمجھنے کا اہم ذریعہ ہے۔ تاہم، آثار قدیمہ کا عمل خود بہت زیادہ خطرے سے دوچار ہے — براہ راست ہدف سطح یا ہدف مدت میں داخل ہو کر آثار قدیمہ کی کھدائی کرنا، ہدف چیز پر جسمانی نقصان، قانون کی خلل اور ثقافتی آلودگی کا سبب بن سکتا ہے۔ آثار قدیمہ کے عمل کو منظم کرنے اور آثار قدیمہ کے خطرے کو کم کرنے کے لیے، ہینگ یوان ژو نے متحد &quot;آثار قدیمہ پروٹوکول کا عمومی خاکہ&quot; وضع کیا ہے، جو تمام بین السطح اور وقت کے پیچھے ہٹنے والی آثار قدیمہ کی سرگرمیوں کے بنیادی آپریشن اصول کے طور پر کام کرتا ہے۔</p><p>آثار قدیمہ پروٹوکول کے بنیادی مقصد کو &quot;تین زیادہ سے زیادہ&quot; کے طور پر خلاصہ کیا جا سکتا ہے: زیادہ سے زیادہ مکمل تاریخی علم حاصل کرنا، ہدف چیز پر مداخلت اور نقصان کو کم سے کم کرنا، آثار قدیمہ کے اہلکاروں کی حفاظت کو زیادہ سے زیادہ یقینی بنانا۔ ان تینوں اہداف کے درمیان اندرونی تناؤ موجود ہے — علم حاصل کرنے کی مکملیت اکثر گہرے رابطے کا مطالبہ کرتی ہے، جبکہ کم مداخلت کا اصول رابطے کی گہرائی کو محدود کرتا ہے۔ آثار قدیمہ پروٹوکول کا تمام ادارہ جاتی ڈیزائن، ان تینوں کے درمیان بہترین توازن تلاش کرنے کے لیے ہے۔</p><p>آثار قدیمہ پروٹوکول درج ذیل منظرناموں پر لاگو ہوتا ہے: نامعلوم سطح پر تہذیب کے کھنڈرات کی آثار قدیمہ کی تحقیقات، وقت کے پیچھے ہٹنے کے ذریعے ناپید تہذیبوں کی تاریخی بحالی، اپنی سطح کے قدیم کھنڈرات پر قانون کی سطح کی گہری آثار قدیمہ، اور قانون ٹوٹی سطح میں قدیم اوشیشوں کی بچاؤ کی کھدائی۔</p><h2 id="_2-آثار-قدیمہ-اسکیم-کے-تین-عناصر" tabindex="-1">2. آثار قدیمہ اسکیم کے تین عناصر <a class="header-anchor" href="#_2-آثار-قدیمہ-اسکیم-کے-تین-عناصر" aria-label="Permalink to &quot;2. آثار قدیمہ اسکیم کے تین عناصر&quot;">​</a></h2><p>ہینگ یوان ژو کی معیاری آثار قدیمہ اسکیم تین بنیادی عناصر پر مشتمل ہے، جسے &quot;آثار قدیمہ کے تین عناصر&quot; کہا جاتا ہے:</p><h3 id="_2-1-کاپی-آئینہ" tabindex="-1">2.1 کاپی آئینہ <a class="header-anchor" href="#_2-1-کاپی-آئینہ" aria-label="Permalink to &quot;2.1 کاپی آئینہ&quot;">​</a></h3><p>کاپی آئینہ جگہ کے قانونی قوانین پر مبنی ایک اعلیٰ درستگی کی کاپی ڈیوائس ہے، جو اصل چیز سے رابطہ کیے بغیر ہدف علاقے میں مادے، توانائی اور معلومات کے ڈھانچے کی 1:1 مکمل کاپی کرنے کی صلاحیت رکھتا ہے۔ کاپی آئینے کے کام کا اصول یہ ہے کہ جگہ کے قوانین کے ذریعے ہدف علاقے کی تمام ذرات کی حالت اور توانائی کے میدان کی تقسیم کو اسکین کیا جاتا ہے، پھر الگ تھلگ جگہ میں ایک بالکل مماثل کاپی دوبارہ بنائی جاتی ہے۔ کاپی کا عمل اصل چیز کی کسی بھی حالت کو تبدیل نہیں کرتا، اس لیے آثار قدیمہ کی جگہ پر کوئی جسمانی مداخلت نہیں کرتا۔</p><p>کاپی آئینے کی کاپی کی درستگی ذیلی ایٹم کی سطح تک پہنچتی ہے، جو ہدف علاقے میں مادے کے ڈھانچے، توانائی کی باقیات، شعور کے نشانات اور یہاں تک کہ وجوہاتی زنجیر کے ٹکڑوں کو مکمل طور پر بحال کرنے کی صلاحیت رکھتی ہے۔ کاپی کی حد آثار قدیمہ کی ضرورت کے مطابق ایڈجسٹ کی جا سکتی ہے، کاپی کی سب سے چھوٹی اکائی ایک واحد آثار قدیمہ کی چیز ہے، سب سے بڑی پوری کھنڈرات کے گروپ کو کور کر سکتی ہے۔ کاپی کا وقت کاپی کی حد کے سائز پر منحصر ہے، ایک واحد آثار قدیمہ کی چیز کی کاپی عام طور پر چند منٹوں میں مکمل ہو جاتی ہے، بڑے کھنڈرات کے گروپ کی کاپی میں کئی دن لگ سکتے ہیں۔</p><h3 id="_2-2-الگ-تھلگ-جگہ" tabindex="-1">2.2 الگ تھلگ جگہ <a class="header-anchor" href="#_2-2-الگ-تھلگ-جگہ" aria-label="Permalink to &quot;2.2 الگ تھلگ جگہ&quot;">​</a></h3><p>الگ تھلگ جگہ جگہ کے قانونی ضابطے کی ٹیکنالوجی کے ذریعے بنایا گیا ایک آزاد قانونی علاقہ ہے، جو کاپی آئینے سے پیدا ہونے والی آثار قدیمہ کی کاپی کو لے جانے اور آثار قدیمہ کے اہلکاروں کے کام کی جگہ کے طور پر استعمال ہوتا ہے۔ الگ تھلگ جگہ اور ہدف سطح یا ہدف مدت کے درمیان مکمل قانونی رکاوٹ سے الگ کیا جاتا ہے، اس بات کو یقینی بناتا ہے کہ آثار قدیمہ کے آپریشن اصل ہدف پر کوئی الٹا اثر نہیں ڈالتے۔</p><p>الگ تھلگ جگہ کے اندر قانونی پیرامیٹرز آثار قدیمہ کی ضرورت کے مطابق حسب ضرورت بنائے جا سکتے ہیں، جن میں شامل ہیں: آثار قدیمہ کی چیزوں کی کاپی کے استحکام کو یقینی بنانے کے لیے ہدف سطح کے ماحولیاتی پیرامیٹرز کی نقل کرنا، آثار قدیمہ کی تحقیق میں مدد کے لیے خصوصی تجزیاتی قانونی میدان قائم کرنا، اور آثار قدیمہ کے اہلکاروں کی توانائی اور شعور کے باہر نکلنے کو روکنے کے لیے سخت آلودگی روک تھام کا میدان قائم کرنا۔ الگ تھلگ جگہ کا سائز ضرورت کے مطابق بڑھایا جا سکتا ہے، سب سے بڑا پورے شہر کی سطح کے کھنڈرات کی کاپی کو رکھ سکتا ہے۔</p><h3 id="_2-3-صرف-علم-کی-واپسی" tabindex="-1">2.3 صرف علم کی واپسی <a class="header-anchor" href="#_2-3-صرف-علم-کی-واپسی" aria-label="Permalink to &quot;2.3 صرف علم کی واپسی&quot;">​</a></h3><p>&quot;صرف علم کی واپسی&quot; آثار قدیمہ پروٹوکول کے بنیادی اصولوں میں سے ایک ہے، جس کا مطلب ہے کہ آثار قدیمہ کے عمل میں ہدف چیز سے جو کچھ حاصل کیا جاتا ہے وہ صرف تجریدی علم اور معلومات ہو سکتی ہے، کوئی بھی مادہ، توانائی یا جاندار چیز واپس نہیں کی جا سکتی۔ آثار قدیمہ کے اہلکار الگ تھلگ جگہ میں کاپی کی تحقیق کرنے کے بعد، صرف تحقیق کے نتائج، ڈیٹا ریکارڈ اور تجزیاتی رپورٹ کو خالص معلومات کی شکل میں اپنی سطح پر واپس لا سکتے ہیں، کاپی خود اور کاپی سے نکالا گیا کوئی بھی مادے کا نمونہ الگ تھلگ جگہ میں ہی تباہ کرنا ضروری ہے۔</p><p>اس اصول کا بنیادی مقصد بین السطح آلودگی اور ٹائم لائن کی خلل کو روکنا ہے۔ یہاں تک کہ کاپی سے نکالا گیا ایک دھول کا ذرہ بھی ہدف سطح کی قانونی معلومات لے سکتا ہے، ایک بار اپنی سطح کے قانونی نیٹ ورک میں داخل ہونے پر، غیر متوقع سلسلہ واکنش کا باعث بن سکتا ہے۔ لہذا، &quot;صرف علم کی واپسی&quot; کوئی قابل گفتگو آپریشن تجویز نہیں ہے، بلکہ قانونی زبردستی طاقت والا ایک سخت اصول ہے۔</p><h2 id="_3-آثار-قدیمہ-کے-آپریشن-کا-معیاری-عمل" tabindex="-1">3. آثار قدیمہ کے آپریشن کا معیاری عمل <a class="header-anchor" href="#_3-آثار-قدیمہ-کے-آپریشن-کا-معیاری-عمل" aria-label="Permalink to &quot;3. آثار قدیمہ کے آپریشن کا معیاری عمل&quot;">​</a></h2><p>ایک مکمل بین السطح یا وقت کے پیچھے ہٹنے والی آثار قدیمہ کے آپریشن درج ذیل معیاری عمل پر عمل کرتا ہے:</p><table tabindex="0"><thead><tr><th>مرحلہ</th><th>آپریشن کا مواد</th><th>ذمہ دار فریق</th><th>مدت کا حوالہ</th></tr></thead><tbody><tr><td>پہلا مرحلہ: پروجیکٹ کی منظوری</td><td>آثار قدیمہ کی درخواست جمع کروانا، آثار قدیمہ کے اہداف، دائرہ کار اور اسکیم کو واضح کرنا، A سطح کی گزر کی اجازت یا پیچھے ہٹنے کی اجازت حاصل کرنا</td><td>آثار قدیمہ ٹیم→سطح انتظامیہ بیورو/وقت قانون کمیٹی</td><td>7-30 دن</td></tr><tr><td>دوسرا مرحلہ: پہلے مشاہدہ</td><td>&quot;پہلے مشاہدہ پھر محدود مداخلت&quot; کے رہنما اصول کے مطابق، ہدف علاقے میں 72 گھنٹے سے زیادہ خالص مشاہدہ کرنا</td><td>آثار قدیمہ ٹیم</td><td>72 گھنٹے سے زیادہ</td></tr><tr><td>تیسرا مرحلہ: کاپی آئینہ کی تعیناتی</td><td>ہدف علاقے کے قریب محفوظ جگہ پر کاپی آئینہ تعینات کرنا، کاپی کی حد اور درستگی کے پیرامیٹرز مقرر کرنا</td><td>ٹیکنیکل گروپ</td><td>چند گھنٹے سے کئی دن</td></tr><tr><td>چوتھا مرحلہ: کاپی کی تخلیق</td><td>کاپی آئینہ چالو کرنا، ہدف علاقے کو پہلے سے بنائے گئے الگ تھلگ جگہ میں مکمل طور پر کاپی کرنا</td><td>ٹیکنیکل گروپ</td><td>چند منٹ سے کئی دن</td></tr><tr><td>پانچواں مرحلہ: الگ تھلگ جگہ میں آثار قدیمہ</td><td>آثار قدیمہ کے اہلکار الگ تھلگ جگہ میں داخل ہوتے ہیں، کاپی کی منظم کھدائی، تجزیہ اور تحقیق کرتے ہیں</td><td>آثار قدیمہ ٹیم</td><td>چند دن سے کئی سال</td></tr><tr><td>چھٹا مرحلہ: علم کی تنظیم</td><td>آثار قدیمہ کے نتائج کو ترتیب دینا، تحقیقی رپورٹ اور علمی ڈیٹا بیس بنانا، اس بات کو یقینی بنانا کہ تمام نتائج خالص معلومات کی شکل میں ہیں</td><td>آثار قدیمہ ٹیم</td><td>چند دن سے کئی ماہ</td></tr><tr><td>ساتواں مرحلہ: انخلاء اور تباہی</td><td>آثار قدیمہ کے اہلکار الگ تھلگ جگہ سے انخلاء کرتے ہیں، تمام کاپی مادے اور توانائی کی باقیات کو تباہ کرتے ہیں، الگ تھلگ جگہ بند کرتے ہیں</td><td>ٹیکنیکل گروپ+نگرانی گروپ</td><td>چند گھنٹے</td></tr><tr><td>آٹھواں مرحلہ: بعد میں آڈٹ</td><td>مکمل آثار قدیمہ رپورٹ جمع کروانا، وقت قانون آڈیٹ کمیٹی یا سطح انتظامیہ بیورو کی بعد میں آڈیٹ قبول کرنا</td><td>آڈیٹ کمیٹی</td><td>30 دن کے اندر</td></tr></tbody></table><h2 id="_4-آثار-قدیمہ-کے-اہلکاروں-کی-قابلیت-اور-اخلاقی-تقاضے" tabindex="-1">4. آثار قدیمہ کے اہلکاروں کی قابلیت اور اخلاقی تقاضے <a class="header-anchor" href="#_4-آثار-قدیمہ-کے-اہلکاروں-کی-قابلیت-اور-اخلاقی-تقاضے" aria-label="Permalink to &quot;4. آثار قدیمہ کے اہلکاروں کی قابلیت اور اخلاقی تقاضے&quot;">​</a></h2><p>بین السطح اور وقت کے پیچھے ہٹنے والی آثار قدیمہ میں مصروف افراد کے پاس درج ذیل قابلیت ہونی چاہیے: جگہ قانونی ضابطے کے نظام کا تیسرا مرحلہ یا اس سے زیادہ سادھک، آثار قدیمہ اخلاقی کمیٹی سے قابلیت کا سرٹیفکیٹ، 100 گھنٹے سے زیادہ سمولیشن آثار قدیمہ کی تربیت مکمل، اور سمبیوسس قانون کی خلاف ورزی کا کوئی ریکارڈ نہیں۔</p><p>آثار قدیمہ کے اہلکاروں کو درج ذیل اخلاقی تقاضوں کی تعمیل کرنی چاہیے: ہدف تہذیب کی ثقافت اور عقائد کا احترام کرنا، تحقیق میں ثقافتی امتیازی سلوک یا قدرتی فیصلہ کرنا منع ہے؛ آثار قدیمہ کی جگہ کی سالمیت کی حفاظت کرنا، آثار قدیمہ کی چیزیں حاصل کرنے کے لیے کھنڈرات کے ڈھانچے کو تباہ کرنا منع ہے؛ آثار قدیمہ کی دریافتوں کو سچی طرح ریکارڈ اور رپورٹ کرنا، آثار قدیمہ کے ڈیٹا کو تبدیل کرنا یا چھپانا منع ہے؛ اور &quot;صرف علم کی واپسی&quot; کے اصول کی تعمیل کرنا، الگ تھلگ جگہ سے باہر نکلتے وقت ذاتی طور پر کوئی بھی مادے کا نمونہ لے جانا منع ہے۔</p><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>آثار قدیمہ پروٹوکول کا عمومی خاکہ ہینگ یوان ژو کی طرف سے علم کی کھوج اور تہذیب کی حفاظت کے درمیان قائم کیا گیا ادارہ جاتی پل ہے۔ یہ تین عناصر — کاپی آئینہ، الگ تھلگ جگہ اور صرف علم کی واپسی — کو تکنیکی مدد کے طور پر، معیاری عمل کو آپریشن فریم ورک کے طور پر، اور اہلکاروں کی قابلیت اور اخلاقی تقاضوں کو انسانی ضمانت کے طور پر لیتا ہے، &quot;کم آلودگی، اعلیٰ کارکردگی، قابل ٹریس&quot; کا ایک آثار قدیمہ پیراڈائم بناتا ہے۔ یہ پیراڈائم اس بات کو یقینی بناتا ہے کہ ہینگ یوان ژو تاریخی حقیقت کی تلاش کرتے ہوئے، ہمیشہ دوسری تہذیبوں اور دوروں کے لیے بلند ترین احترام برقرار رکھتا ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>85-کاپی آئینہ دور دراز آثار قدیمہ اسکیم</li><li>86-الگ تھلگ جگہ کم آلودگی کا عمل</li><li>87-صرف علم کی واپسی کا اصول</li></ul>',27)])])}const q=a(o,[["render",h]]);export{s as __pageData,q as default};
